scriptedVariables.script:
const responseData = typeof response !== "undefined" ? response?.data : undefined;
const payloadData = typeof payload !== "undefined" ? payload : undefined;
const scopedDevices = typeof devices !== "undefined" ? devices : undefined;
const input = responseData?.devices ?? payloadData?.devices ?? scopedDevices ?? [];
if (!Array.isArray(input)) return [];
return input.map((device) => {
  const item = device ?? {};
  const { user, summary, ...rest } = item;
  const userData = user ?? {};
  const summaryData = summary ?? {};
  return {
    ...rest,
    device_id: rest.device_id !== undefined && rest.device_id !== null ? String(rest.device_id) : rest.device_id,
    imei: rest.imei !== undefined && rest.imei !== null ? String(rest.imei) : rest.imei,
    user_id: userData.user_id !== undefined && userData.user_id !== null ? String(userData.user_id) : userData.user_id,
    user_name: userData.user_name,
    user_email: userData.user_email,
    profile_count: summaryData.profile_count,
    app_count: summaryData.app_count,
    doc_count: summaryData.doc_count,
    group_count: summaryData.group_count
  };
});

